cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// ---------------------------------------------------------------------------
// Tiled cooperative kernel for the common case stride == 1.
// Uses a shared-memory input tile (with halo) reused across the whole output
// tile and looped over input channels, avoiding one-thread-per-output-element
// redundant global loads.
// ---------------------------------------------------------------------------
template <int TILE>
__global__ void ct3d_tiled_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ bias_ptr,
    float* __restrict__ y_ptr,
    int N, int Cin, int D, int H, int W,
    int Cout, int K,
    int Dout, int Hout, int Wout,
    int padding_, int dilation_,
    int n_td, int n_th, int n_tw,
    int sbuf_dim)
{
    extern __shared__ float smem[];

    int n  = blockIdx.x;
    int co = blockIdx.y;
    int tile_lin = blockIdx.z;
    int tile_w = tile_lin % n_tw;
    int tmp    = tile_lin / n_tw;
    int tile_h = tmp % n_th;
    int tile_d = tmp / n_th;

    int od0 = tile_d * TILE;
    int oh0 = tile_h * TILE;
    int ow0 = tile_w * TILE;

    int dz = threadIdx.z, dy = threadIdx.y, dx = threadIdx.x;
    int od = od0 + dz, oh = oh0 + dy, ow = ow0 + dx;

    auto x_t = make_tensor(make_gmem_ptr(x_ptr),
                            make_shape(N, Cin, D, H, W),
                            make_stride(Cin * D * H * W, D * H * W, H * W, W, 1));
    auto w_t = make_tensor(make_gmem_ptr(w_ptr),
                            make_shape(Cin, Cout, K, K, K),
                            make_stride(Cout * K * K * K, K * K * K, K * K, K, 1));
    auto y_t = make_tensor(make_gmem_ptr(y_ptr),
                            make_shape(N, Cout, Dout, Hout, Wout),
                            make_stride(Cout * Dout * Hout * Wout, Dout * Hout * Wout, Hout * Wout, Wout, 1));

    auto s_t = make_tensor(make_smem_ptr(smem),
                            make_shape(sbuf_dim, sbuf_dim, sbuf_dim),
                            make_stride(sbuf_dim * sbuf_dim, sbuf_dim, 1));

    int halo = (K - 1) * dilation_;
    int ID0 = od0 + padding_ - halo;
    int IH0 = oh0 + padding_ - halo;
    int IW0 = ow0 + padding_ - halo;

    int tid = (dz * TILE + dy) * TILE + dx;
    int nthreads = TILE * TILE * TILE;
    int total_s = sbuf_dim * sbuf_dim * sbuf_dim;

    float acc = 0.0f;
    bool valid_out = (od < Dout) && (oh < Hout) && (ow < Wout);

    for (int ci = 0; ci < Cin; ++ci) {
        for (int idx = tid; idx < total_s; idx += nthreads) {
            int d_l = idx / (sbuf_dim * sbuf_dim);
            int rem = idx % (sbuf_dim * sbuf_dim);
            int h_l = rem / sbuf_dim;
            int w_l = rem % sbuf_dim;

            int idg = ID0 + d_l;
            int ihg = IH0 + h_l;
            int iwg = IW0 + w_l;

            float v = 0.0f;
            if (idg >= 0 && idg < D && ihg >= 0 && ihg < H && iwg >= 0 && iwg < W) {
                v = x_t(n, ci, idg, ihg, iwg);
            }
            s_t(d_l, h_l, w_l) = v;
        }
        __syncthreads();

        if (valid_out) {
            for (int kd = 0; kd < K; ++kd) {
                int id_l = dz + (K - 1 - kd) * dilation_;
                for (int kh = 0; kh < K; ++kh) {
                    int ih_l = dy + (K - 1 - kh) * dilation_;
                    for (int kw = 0; kw < K; ++kw) {
                        int iw_l = dx + (K - 1 - kw) * dilation_;
                        acc += s_t(id_l, ih_l, iw_l) * w_t(ci, co, kd, kh, kw);
                    }
                }
            }
        }
        __syncthreads();
    }

    if (valid_out) {
        if (bias_ptr != nullptr) acc += bias_ptr[co];
        y_t(n, co, od, oh, ow) = acc;
    }
}

// ---------------------------------------------------------------------------
// Fallback: general (stride != 1) direct kernel, one thread per output.
// Only used for non-default stride, kept simple & correct.
// ---------------------------------------------------------------------------
__global__ void ct3d_naive_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ bias_ptr,
    float* __restrict__ y_ptr,
    int N, int Cin, int D, int H, int W,
    int Cout, int K,
    int Dout, int Hout, int Wout,
    int stride_, int padding_, int dilation_)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * Cout * Dout * Hout * Wout;
    if (idx >= total) return;

    int ow = idx % Wout; int t = idx / Wout;
    int oh = t % Hout; t /= Hout;
    int od = t % Dout; t /= Dout;
    int co = t % Cout; t /= Cout;
    int n  = t;

    auto x_t = make_tensor(make_gmem_ptr(x_ptr),
                            make_shape(N, Cin, D, H, W),
                            make_stride(Cin * D * H * W, D * H * W, H * W, W, 1));
    auto w_t = make_tensor(make_gmem_ptr(w_ptr),
                            make_shape(Cin, Cout, K, K, K),
                            make_stride(Cout * K * K * K, K * K * K, K * K, K, 1));

    float acc = 0.0f;
    for (int ci = 0; ci < Cin; ++ci) {
        for (int kd = 0; kd < K; ++kd) {
            int num_d = od + padding_ - kd * dilation_;
            if (num_d % stride_ != 0) continue;
            int id = num_d / stride_;
            if (id < 0 || id >= D) continue;
            for (int kh = 0; kh < K; ++kh) {
                int num_h = oh + padding_ - kh * dilation_;
                if (num_h % stride_ != 0) continue;
                int ih = num_h / stride_;
                if (ih < 0 || ih >= H) continue;
                for (int kw = 0; kw < K; ++kw) {
                    int num_w = ow + padding_ - kw * dilation_;
                    if (num_w % stride_ != 0) continue;
                    int iw = num_w / stride_;
                    if (iw < 0 || iw >= W) continue;
                    acc += x_t(n, ci, id, ih, iw) * w_t(ci, co, kd, kh, kw);
                }
            }
        }
    }
    if (bias_ptr != nullptr) acc += bias_ptr[co];

    long y_stride_n = (long)Cout * Dout * Hout * Wout;
    long y_stride_c = (long)Dout * Hout * Wout;
    long y_stride_d = (long)Hout * Wout;
    long y_stride_h = (long)Wout;
    y_ptr[n * y_stride_n + co * y_stride_c + od * y_stride_d + oh * y_stride_h + ow] = acc;
}

torch::Tensor cute_conv_transpose3d(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                                     int64_t stride, int64_t padding, int64_t output_padding, int64_t dilation) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat, "expect float32");
    TORCH_CHECK(x.dim() == 5 && weight.dim() == 5, "x must be 5D (N,C,D,H,W), weight must be 5D");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    bool has_bias = bias.numel() > 0;
    torch::Tensor b_c;
    const float* bias_ptr = nullptr;
    if (has_bias) {
        b_c = bias.contiguous();
        bias_ptr = b_c.data_ptr<float>();
    }

    int N   = (int)x_c.size(0);
    int Cin = (int)x_c.size(1);
    int D   = (int)x_c.size(2);
    int H   = (int)x_c.size(3);
    int W   = (int)x_c.size(4);

    int Cout = (int)w_c.size(1);
    int K    = (int)w_c.size(2);

    int s   = (int)stride;
    int p   = (int)padding;
    int op  = (int)output_padding;
    int dil = (int)dilation;

    int Dout = (D - 1) * s - 2 * p + dil * (K - 1) + op + 1;
    int Hout = (H - 1) * s - 2 * p + dil * (K - 1) + op + 1;
    int Wout = (W - 1) * s - 2 * p + dil * (K - 1) + op + 1;

    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x_c.options());

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    if (s == 1) {
        const int TILE = 8;
        int n_td = (Dout + TILE - 1) / TILE;
        int n_th = (Hout + TILE - 1) / TILE;
        int n_tw = (Wout + TILE - 1) / TILE;
        int sbuf_dim = TILE + (K - 1) * dil;
        size_t smem_bytes = (size_t)sbuf_dim * sbuf_dim * sbuf_dim * sizeof(float);

        dim3 block(TILE, TILE, TILE);
        dim3 grid(N, Cout, n_td * n_th * n_tw);

        cudaFuncSetAttribute(ct3d_tiled_kernel<TILE>,
                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                              (int)smem_bytes);

        ct3d_tiled_kernel<TILE><<<grid, block, smem_bytes, stream>>>(
            x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
            N, Cin, D, H, W, Cout, K, Dout, Hout, Wout,
            p, dil, n_td, n_th, n_tw, sbuf_dim);
    } else {
        int total = N * Cout * Dout * Hout * Wout;
        int threads = 256;
        int blocks = (total + threads - 1) / threads;
        ct3d_naive_kernel<<<blocks, threads, 0, stream>>>(
            x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
            N, Cin, D, H, W, Cout, K, Dout, Hout, Wout,
            s, p, dil);
    }

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE conv_transpose3d kernel launch failed");
    return y;
}
